"""Enumerate all four kinds of exact od/ed exclusivity on public training pages."""
import json

from vs import corpus
from voynich_currier_variant_audit import EDITIONS, by_language, sum_stocks, word_stock
from voynich_currier_line_order import odds_to_eds


def exclusive_edges(stock_a, stock_b, minimum=2):
    possible = sorted(stock_a.keys() | stock_b.keys())
    results = {f'{grp}_only_{variant}': set() for grp in ('A', 'B') for variant in ('od', 'ed')}
    for od in possible:
        for ed in sorted(odds_to_eds(od)):
            counts = [(od, 'od', ed), (ed, 'ed', od)]
            for exclusive, label, shared in counts:
                if stock_a[shared] == 0 or stock_b[shared] == 0:
                    continue
                for own, other, group in ((stock_a, stock_b, 'A'), (stock_b, stock_a, 'B')):
                    if own[exclusive] >= minimum and other[exclusive] == 0:
                        results[f'{group}_only_{label}'].add((od, ed))
    return results


def classify(edition, scope=None, minimum=2):
    train, _ = corpus.split_pages('practice', edition)
    groups = by_language([(page, word_stock(page)) for page in train
                          if scope is None or page.section == scope])
    a, b = (sum_stocks(stock for _, stock in groups[group]) for group in ('A', 'B'))
    return exclusive_edges(a, b, minimum=minimum)


if __name__ == '__main__':
    records = {}
    for scope_name, scope in (('all', None), ('H', 'H')):
        records[scope_name] = {}
        for minimum in (2, 4):
            selected = {ed: classify(ed, scope, minimum) for ed in EDITIONS}
            sizes = {ed: {direction: len(pairs) for direction, pairs in directions.items()}
                     for ed, directions in selected.items()}
            cross = {direction: sorted(selected['zl'][direction] & selected['it'][direction])
                     for direction in selected['zl']}
            records[scope_name][minimum] = {'sizes': sizes, 'verified_ZL_IT': cross}
    print(json.dumps(records, indent=2))

