"""Check local od/ed order in B while holding leaves, lines, and distances fixed."""
import json
import random
import re
from collections import Counter, defaultdict
from functools import lru_cache
from itertools import product

from vs import corpus
from voynich_currier_variant_audit import ALTERNATIVES, EDITIONS, PAIRS, PARTS, leaf_id

FOUR = frozenset(PAIRS[:4])
ENDPOINTS = ('interior', 'all_slots')

@lru_cache(maxsize=None)
def odds_to_eds(word):
    if not ALTERNATIVES.fullmatch(word):
        return frozenset()
    return frozenset(word[:m.start()] + 'e' + word[m.start() + 1:]
                     for m in re.finditer('od', word))


def line_pairs(words):
    for left, first in enumerate(words):
        for right in range(left + 1, min(left + 11, len(words))):
            second = words[right]
            if second in odds_to_eds(first):
                yield (first, second), 1
            if first in odds_to_eds(second):
                yield (second, first), -1


def measure(pages, endpoint):
    counts = {'paper_four': defaultdict(Counter), 'all_single_site': defaultdict(Counter)}
    for page in pages:
        if page.language != 'B':
            continue
        for line in page.lines:
            if line.unit != 'P':
                continue
            words = line.words[1:-1] if endpoint == 'interior' else line.words
            for pair, direction in line_pairs(words):
                counts['all_single_site'][leaf_id(page)][direction] += 1
                if pair in FOUR:
                    counts['paper_four'][leaf_id(page)][direction] += 1
    return {scope: assess(leaves) for scope, leaves in counts.items()}


def assess(leaves):
    ahead = sum(count[1] for count in leaves.values())
    behind = sum(count[-1] for count in leaves.values())
    effects = [count[1] - count[-1] for count in leaves.values() if count[1] != count[-1]]
    observed = ahead - behind
    if len(effects) <= 15:
        permutations = 2 ** len(effects)
        upper_tail = sum(sum(s * e for s, e in zip(signs, effects)) >= observed
                         for signs in product((1, -1), repeat=len(effects))) / permutations
        method = 'all_sign_flips'
    else:
        rng = random.Random(5267)
        permutations = 9999
        exceedances = 0
        for _ in range(permutations):
            signed_sum = sum(effect if rng.getrandbits(1) else -effect for effect in effects)
            exceedances += signed_sum >= observed
        upper_tail = (exceedances + 1) / (permutations + 1)
        method = 'random_sign_flips_plus_one'
    return {'od_before_ed': ahead, 'ed_before_od': behind, 'leaves_with_pairs': len(leaves),
            'leaves_with_unbalanced_direction': len(effects), 'upper_tail_rank': upper_tail,
            'flip_method': method, 'sign_patterns': permutations}


if __name__ == '__main__':
    result = {ed: {partition: {endpoint: measure(pages, endpoint) for endpoint in ENDPOINTS}
                   for partition, pages in zip(PARTS, corpus.split_pages('practice', ed))}
              for ed in EDITIONS}
    print(json.dumps(result, indent=2))

