"""Audit the literal od/ed claims in Timm v3, using public practice pages."""
import json
import random
import re
from collections import Counter, defaultdict
from statistics import median

from vs import corpus

EDITIONS = ('zl', 'it', 'rf')
PAIRS = (('chody', 'chedy'), ('chodar', 'chedar'), ('chodal', 'chedal'),
         ('qokeody', 'qokeedy'), ('cthody', 'cthedy'))
WORD_FORMS = {word for pair in PAIRS for word in pair}
ALTERNATIVES = re.compile(r'[a-z]+\Z')
PARTS = ('train', 'evaluation')


def leaf_id(page):
    return re.match(r'f\d+', page.id)[0]


def word_stock(page):
    return Counter(word for line in page.lines if line.unit == 'P'
                   for word in line.words if ALTERNATIVES.fullmatch(word))


def sum_stocks(stocks):
    total = Counter()
    for stock in stocks:
        total.update(stock)
    return total


def occurrence_counts(stock):
    return [sum(n * word.count(form) for word, n in stock.items()) for form in ('od', 'ed')]


def fraction(stock):
    odds, eds = occurrence_counts(stock)
    return eds / (odds + eds) if odds + eds else None


def describe(rows):
    stock = sum_stocks(stock for _, stock in rows)
    return {
        'pages': len(rows),
        'leaves': len({leaf_id(page) for page, _ in rows}),
        'words': stock.total(),
        'pairs': {a + '/' + b: [stock[a], stock[b]] for a, b in PAIRS},
        'od_ed_sites': occurrence_counts(stock),
    }


def leaf_stocks(rows):
    grouped = defaultdict(Counter)
    for page, stock in rows:
        grouped[leaf_id(page)].update(stock)
    return dict(grouped)


def by_language(rows):
    return {language: [(p, s) for p, s in rows if p.language == language]
            for language in ('A', 'B')}


def matched_herbal_leaves(rows):
    groups = by_language([(p, s) for p, s in rows if p.section == 'H'])
    a = list(leaf_stocks(groups['A']).values())
    b = list(leaf_stocks(groups['B']).values())
    b_stock = sum_stocks(b)
    b_fraction = fraction(b_stock)
    rng = random.Random(5293)
    draws = []
    for _ in range(1000):
        a_stock = sum_stocks(rng.sample(a, len(b)))
        draws.append([b_fraction - fraction(a_stock), a_stock.total()])
    rates = sorted(rate for rate, _ in draws)
    return {
        'A_available_leaves': len(a), 'B_matched_leaves': len(b),
        'B_words': b_stock.total(), 'B_ed_fraction': b_fraction,
        'median_A_sample_words': median(n for _, n in draws),
        'B_minus_A_fraction_quantiles': [rates[i] for i in (24, 499, 974)],
        'positive_draws': sum(rate > 0 for rate in rates), 'draws': len(draws),
    }


def hand_three_star(rows):
    groups = by_language([(p, s) for p, s in rows if p.section == 'S' and p.hand == '3'])
    all_rates = {language: {leaf: fraction(s) for leaf, s in leaf_stocks(part).items()}
                 for language, part in groups.items()}
    a_rate, = all_rates['A'].values()
    b_rates = [rate for rate in all_rates['B'].values() if rate is not None]
    return {
        'counts': {language: describe(part) for language, part in groups.items()},
        'A_leaf_rates': all_rates['A'], 'B_leaves_informative': len(b_rates),
        'B_leaf_rate_range': [min(b_rates), max(b_rates)],
        'B_leaves_above_A': sum(rate > a_rate for rate in b_rates),
        'B_leaves_equal_A': sum(rate == a_rate for rate in b_rates),
    }


def candidate_loci(pages_by_edition):
    loci = {}
    for edition, pages in pages_by_edition.items():
        loci[edition] = {
            line.id: words
            for page in pages
            if page.language == 'A'
            for line in page.lines
            if line.unit == 'P'
            for words in (line.words,)
            if WORD_FORMS.intersection(words)
        }
    matches = {}
    for word in ('chedy', 'chedal', 'cthody', 'cthedy', 'chedar', 'qokeedy'):
        per_edition = {ed: {locus for locus, words in entries.items() if word in words}
                       for ed, entries in loci.items()}
        common = sorted(set.intersection(*per_edition.values()))
        adjoining = []
        for locus in common:
            context = []
            for ed in EDITIONS:
                words = loci[ed][locus]
                pairs = set(zip(words, words[1:]))
                context.append({pair for pair in pairs if word in pair
                                and all(ALTERNATIVES.fullmatch(w) for w in pair)})
            if set.intersection(*context):
                adjoining.append(locus)
        matches[word] = {
            'loci_each_edition': {ed: sorted(ids) for ed, ids in per_edition.items()},
            'all_three_same_locus': common,
            'also_agree_on_left_or_right_token': adjoining,
        }
    return matches


def collect():
    result = {'editions': {}, 'practice_public_only': True}
    pages_by_part = {part: {} for part in PARTS}
    for edition in EDITIONS:
        edition_results = {}
        rows = []
        for partition, pages in zip(PARTS, corpus.split_pages('practice', edition)):
            pages_by_part[partition][edition] = pages
            selected = [(page, word_stock(page)) for page in pages if page.language in ('A', 'B')]
            selected = [(page, stock) for page, stock in selected if stock]
            rows.extend(selected)
            edition_results[partition] = {
                language: describe(part) for language, part in by_language(selected).items()
            }
        edition_results['herbal_match'] = matched_herbal_leaves(rows)
        edition_results['stars_3_same_hand'] = hand_three_star(rows)
        result['editions'][edition] = edition_results
    result['A_locus_agreement'] = {part: candidate_loci(eds) for part, eds in pages_by_part.items()}
    return result


if __name__ == '__main__':
    print(json.dumps(collect(), indent=2, ensure_ascii=False))
